        c.mintToken(address(this), amount + extraMint);
        uint256 supplyBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));
        require(balBefore >= amount + extraMint);
        // insufficient balance: send more than we hold after a burn of everything
        c.burn(c.balanceOf(address(this)));
        uint256 balAfterBurn = c.balanceOf(address(this));
        bool reverted;
        try c.transfer(address(0x1), balAfterBurn + 1) { reverted = false; }
        catch { reverted = true; }
        assert(reverted && c.totalSupply() == supplyBefore - (amount + extraMint) && c.balanceOf(address(this)) == 0);
    }
    receive() external payable {}
}

