contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address to, uint256 value, uint256 initialSupply, uint256 transferValue) public {
        require(from != to && from != address(this) && to != address(0) && from != address(0));
        require(value > 0 && transferValue > 0);
        c.mintToken(from, value);
        c.mintToken(to, transferValue);
        uint256 supplyBefore = c.totalSupply();
        uint256 fromBalBefore = c.balanceOf(from);
        uint256 toBalBefore = c.balanceOf(to);
        bool reverted;
        // attempt transfer of transferValue from this contract's own account when its balance is too low
        uint256 selfBal = c.balanceOf(address(this));
        if (selfBal < transferValue) {
            try c.transfer(to, transferValue) { reverted = false; } catch { reverted = true; }
        } else {
            // force insufficient balance scenario using 'from': zero its balance is impossible, so instead
            // transfer from this must succeed; assert nothing about it.
            reverted = false;
        }
        assert(reverted);
        assert(c.totalSupply() == supplyBefore && c.balanceOf(from) == fromBalBefore && c.balanceOf(to) == toBalBefore);
    }
    receive() external payable {}
}

